def confined(path: str) -> bool:
    """True when path, taken relative to its directory, stays inside that directory."""
    ex confined("a.txt") == True
    ex confined("sub/../a.txt") == True
    ex confined("../x") == False
    ex confined("sub/../../x") == False
    ex confined("/etc/passwd") == False
    if path.startswith("/"):
        return False
    depth = 0
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of notes/path, or "" when path leaves notes or the file cannot be read.
    Reads go through fs narrowed to the directory notes."""
    post confined(path) or out == ""
    if not confined(path):
        return ""
    text = ""
    with fs = fs.sub("notes"):
        text = fs.read_text(path) else ""
    return text
